import PennantCore
import Foundation

/// The components Pennant's cards are drawn with (json-render's chat components, Web/cards), as the model is told about
/// them and as a card is checked against them before it's posted. The data is generated by Web/cards/build.mjs into
/// CardCatalog+Generated.swift.
enum CardCatalog {
    struct Component: Decodable {
        /// json-render's own one-line description: the props, then what it's for.
        var line: String
        /// Whether it holds other elements.
        var children: Bool
        /// Its props as JSON Schema.
        var props: JSONValue
    }

    struct Data: Decodable {
        var components: [String: Component]
        var actions: [String]
    }

    static let data: Data = {
        do { return try JSONDecoder().decode(Data.self, from: Foundation.Data(generatedJSON.utf8)) } catch { fatalError("CardCatalog+Generated.swift doesn't decode: \(error)") }
    }()

    /// One line per component, in a steady order, for the tool's description.
    static var componentLines: String {
        data.components.keys.sorted().map { "- \($0): \(data.components[$0]!.line)" }.joined(separator: "\n")
    }

    // MARK: Checking a card

    /// What's wrong with a card, one problem a line, so the model can fix them all at once; empty when it can be drawn.
    static func problems(in spec: JSONValue, limit: Int = 15) -> [String] {
        var out: [String] = []
        func add(_ problem: String) { if out.count < limit { out.append(problem) } }
        guard let elements = spec["elements"]?.objectValue, !elements.isEmpty else { return ["The card needs \"elements\": an object of elements by key."] }
        guard let root = spec["root"]?.stringValue else { return ["The card needs \"root\": the key of its top element."] }
        if elements[root] == nil { add("\"root\" is \"\(root)\", which isn't one of the elements.") }
        if let state = spec["state"], state.objectValue == nil { add("\"state\" must be an object.") }

        for key in elements.keys.sorted() {
            let element = elements[key]!
            guard element.objectValue != nil else { add("\(key): must be an object with type, props and children."); continue }
            guard let type = element["type"]?.stringValue else { add("\(key): has no \"type\"."); continue }
            guard let component = data.components[type] else {
                add("\(key): \"\(type)\" isn't a component here. Use one of: \(data.components.keys.sorted().joined(separator: ", ")).")
                continue
            }
            if let props = element["props"] {
                if props.objectValue == nil { add("\(key) (\(type)): \"props\" must be an object.") }
                else { check(props, against: component.props, at: "\(key) (\(type)) props", add) }
            } else {
                check(.object([:]), against: component.props, at: "\(key) (\(type)) props", add)
            }
            let children = element["children"]?.arrayValue ?? []
            if element["children"] != nil, element["children"]?.arrayValue == nil { add("\(key): \"children\" must be an array of element keys.") }
            if !children.isEmpty, !component.children { add("\(key): a \(type) holds no children; put them in a Stack or Card instead.") }
            for child in children {
                guard let name = child.stringValue else { add("\(key): children must be element keys (strings)."); continue }
                if elements[name] == nil { add("\(key): child \"\(name)\" isn't one of the elements.") }
            }
            if let on = element["on"] {
                guard let events = on.objectValue else { add("\(key): \"on\" must be an object like {\"press\": {\"action\": \"reply\", \"params\": {\"text\": …}}}."); continue }
                for (event, binding) in events {
                    for b in binding.arrayValue ?? [binding] { checkAction(b, at: "\(key) on.\(event)", add) }
                }
            }
            if element["props"]?["on"] != nil || element["props"]?["action"] != nil { add("\(key): \"on\" goes on the element, beside \"props\", not inside it.") }
        }
        return out
    }

    private static func checkAction(_ binding: JSONValue, at path: String, _ add: (String) -> Void) {
        guard let action = binding["action"]?.stringValue else { add("\(path): needs \"action\": reply or open."); return }
        let params = binding["params"]
        switch action {
        case "reply":
            if (params?["text"]?.stringValue ?? "").isEmpty { add("\(path): reply needs params.text, the words it sends as the owner's reply.") }
        case "open":
            let url = params?["url"]?.stringValue.flatMap(URL.init(string:))
            if url == nil || !["http", "https", "mailto"].contains(url?.scheme?.lowercased() ?? "") { add("\(path): open needs params.url, a web link.") }
        default:
            add("\(path): \"\(action)\" isn't an action here. Use reply or open.")
        }
    }

    /// A value against the subset of JSON Schema the catalog's props use: type, enum, anyOf, properties, required,
    /// additionalProperties and items. A dynamic value (`{"$state": …}` and the like) passes; json-render reads it.
    private static func check(_ value: JSONValue, against schema: JSONValue, at path: String, _ add: (String) -> Void) {
        if let o = value.objectValue, o.keys.contains(where: { $0.hasPrefix("$") }) { return }
        if let options = schema["anyOf"]?.arrayValue {
            if !options.contains(where: { matches(value, $0) }) { add("\(path): \(describe(value)) doesn't fit; expected \(expected(schema)).") }
            return
        }
        if !matches(value, schema, shallow: true) { add("\(path): \(describe(value)) doesn't fit; expected \(expected(schema))."); return }
        if let object = value.objectValue, let properties = schema["properties"]?.objectValue {
            for name in schema["required"]?.arrayValue?.compactMap(\.stringValue) ?? [] where object[name] == nil {
                if let p = properties[name], allowsNull(p) { continue }
                add("\(path): \"\(name)\" is missing.")
            }
            for (name, v) in object {
                if let p = properties[name] { check(v, against: p, at: "\(path).\(name)", add) }
                else if schema["additionalProperties"] == .bool(false) { add("\(path): \"\(name)\" isn't a prop here (props: \(properties.keys.sorted().joined(separator: ", ")))."); }
            }
        }
        if let array = value.arrayValue, let items = schema["items"] {
            for (i, v) in array.enumerated() { check(v, against: items, at: "\(path)[\(i)]", add) }
        }
    }

    private static func matches(_ value: JSONValue, _ schema: JSONValue, shallow: Bool = false) -> Bool {
        if let o = value.objectValue, o.keys.contains(where: { $0.hasPrefix("$") }) { return true }
        if let options = schema["anyOf"]?.arrayValue { return options.contains { matches(value, $0) } }
        let types = schema["type"].map { $0.arrayValue?.compactMap(\.stringValue) ?? [$0.stringValue].compactMap { $0 } } ?? []
        if !types.isEmpty, !types.contains(where: { is_(value, $0) }) { return false }
        if let allowed = schema["enum"]?.arrayValue, !allowed.contains(value) { return false }
        if shallow { return true }
        var ok = true
        check(value, against: schema, at: "") { _ in ok = false }
        return ok
    }

    private static func is_(_ value: JSONValue, _ type: String) -> Bool {
        switch (type, value) {
        case ("null", .null), ("string", .string), ("boolean", .bool), ("array", .array), ("object", .object): return true
        case ("number", .number): return true
        case ("integer", .number(let n)): return n.rounded() == n
        default: return false
        }
    }

    private static func allowsNull(_ schema: JSONValue) -> Bool {
        if let options = schema["anyOf"]?.arrayValue { return options.contains(where: allowsNull) }
        if let types = schema["type"]?.arrayValue { return types.contains(.string("null")) }
        return schema["type"] == .string("null")
    }

    private static func expected(_ schema: JSONValue) -> String {
        if let options = schema["anyOf"]?.arrayValue { return options.map(expected).filter { $0 != "null" }.joined(separator: " or ") }
        if let allowed = schema["enum"]?.arrayValue { return allowed.map { "\"\($0.stringValue ?? $0.description)\"" }.joined(separator: " | ") }
        let types = schema["type"].map { $0.arrayValue?.compactMap(\.stringValue) ?? [$0.stringValue].compactMap { $0 } } ?? []
        return types.filter { $0 != "null" }.joined(separator: " or ")
    }

    private static func describe(_ value: JSONValue) -> String {
        switch value {
        case .string(let s): return "\"\(s.prefix(40))\""
        case .number, .bool, .null: return value.description
        case .array: return "an array"
        case .object: return "an object"
        }
    }
}
